-- MANUAL Supabase SQL Editor application only. Requires the existing Articles CMS.
-- Re-runnable: seed conflicts never overwrite edited records. No Articles/Auth/storage changes.
begin;
create table if not exists public.holiday_types (
 id uuid primary key default gen_random_uuid(),
 name text not null default '' check(length(name)<=120),
 slug text not null unique check(length(slug) between 1 and 60 and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
 introduction text not null default '' check(length(introduction)<=500),
 heading text not null default '' check(length(heading)<=180),
 body text not null default '' check(length(body)<=150000),
 image text not null default '' check(image='' or image in ('/images/destinations/family.jpg','/images/destinations/cruise.jpg','/images/destinations/couples.jpg','/images/destinations/city.jpg','/images/destinations/different.jpg','/images/destinations/accessible.jpg') or image ~ '^[a-f0-9-]{36}-[a-z0-9-]{1,80}\.webp$'),
 image_alt text not null default '' check(length(image_alt)<=300),
 image_position text not null default '50% 50%' check(image_position ~ '^(100|[0-9]{1,2})% (100|[0-9]{1,2})%$'),
 closing_heading text not null default 'Have a holiday in mind?' check(length(closing_heading)<=180),
 closing_body text not null default 'Tell me what you would like from your time away and I can help research the options.' check(length(closing_body)<=1000),
 status text not null default 'draft' check(status in ('draft','published')),
 display_order integer not null default 100,
 is_original boolean generated always as (id in ('b0000000-0000-4000-8000-000000000001'::uuid,'b0000000-0000-4000-8000-000000000002'::uuid,'b0000000-0000-4000-8000-000000000003'::uuid,'b0000000-0000-4000-8000-000000000004'::uuid,'b0000000-0000-4000-8000-000000000005'::uuid,'b0000000-0000-4000-8000-000000000006'::uuid)) stored,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,
 version integer not null default 1,
 check(status<>'published' or (btrim(name)<>'' and btrim(heading)<>'' and btrim(regexp_replace(body,'<[^>]*>','','g'))<>''))
);
create index if not exists holiday_types_public_order on public.holiday_types(display_order,created_at,id) where status='published';
create or replace function public.holiday_type_dates() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' then
   if old.is_original then raise exception 'Original Holiday Types cannot be deleted; unpublish instead' using errcode='22023';end if;
   return old;
 elsif tg_op='UPDATE' then
   if (old.published_at is not null or old.is_original) and new.slug<>old.slug then raise exception 'Published URLs are permanent' using errcode='22023';end if;
   new.id:=old.id;new.created_at:=old.created_at;new.published_at:=old.published_at;new.display_order:=old.display_order;new.version:=old.version+1;
 else
   new.created_at:=now();new.published_at:=null;new.version:=1;
 end if;
 if new.status='published' and new.published_at is null then new.published_at:=now();end if;
 new.updated_at:=now();return new;
end;$$;
drop trigger if exists holiday_type_dates on public.holiday_types;
create trigger holiday_type_dates before insert or update or delete on public.holiday_types for each row execute function public.holiday_type_dates();
revoke all on function public.holiday_type_dates() from public,anon,authenticated;
alter table public.holiday_types enable row level security;
revoke all on public.holiday_types from public,anon,authenticated;
grant select on public.holiday_types to anon,authenticated;
grant insert,update,delete on public.holiday_types to authenticated;
drop policy if exists holiday_types_read on public.holiday_types;
create policy holiday_types_read on public.holiday_types for select using(public.articles_is_admin() or status='published');
drop policy if exists holiday_types_write on public.holiday_types;
create policy holiday_types_write on public.holiday_types for all to authenticated using(public.articles_is_admin()) with check(public.articles_is_admin());

-- Existing copy, local photographs, crops and closing invitations. FAQ content deliberately excluded.
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000001','Family Holidays','family','Beach days, busy days and time together, with the practical details thought through.','A holiday that works for everyone coming along.','<p>Think beyond the swimming pool: rooms, journeys, activities and a realistic family budget all deserve a place in the plan.</p><h2>More than a hotel with a pool</h2><p>A family holiday needs to fit the people travelling. A toddler, a teenager and a grandparent may want quite different things from the same week. I can help compare options around your priorities, rather than treating “family-friendly” as the whole answer.</p><h2>Things worth thinking through</h2><h3>Dates and children’s ages</h3><p>Start with your school holiday dates, any flexibility and the children’s ages when you travel. Check that clubs, activities and facilities suit those ages and your actual travel dates.</p><h3>Rooms and space</h3><p>Think about beds, separate sleeping areas and whether connecting rooms are essential. For multigenerational trips, consider everyone’s preferred pace and how much time you want together. Room arrangements need confirmation for the chosen property.</p><h3>The journey and the everyday details</h3><p>Flight times, transfer length, meals, shade and the walk between your room and facilities can shape each day. A shorter transfer might matter more to you than another facility at the hotel.</p><h3>What value means for your family</h3><p>Compare the whole cost, including meals, activities, baggage and getting around. A lower accommodation price does not necessarily mean a lower overall spend.</p><h2>Styles to explore</h2><h3>Beach and resort stays</h3><p>A base with space to relax and activities nearby could suit a week together. Check which facilities are included, supervised or charged separately.</p><h3>All-inclusive or self-catering?</h3><p>All-inclusive may make some spending easier to plan, but inclusions vary. Self-catering gives you more say over meals; allow for shopping, eating out and the practicalities of cooking on holiday.</p><h3>Several generations, one trip</h3><p>A shared villa, apartments or a resort with different room options can be starting points. Privacy, access and activities for different ages deserve equal attention.</p>','/images/destinations/family.jpg','Sunlit beach and turquoise sea','50% 55%','Have a family trip in mind?','Tell me who is coming, when you can travel and what would make the holiday work for you.','published',1) on conflict(id) do nothing;
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000002','Cruises','cruises','Get to know the choices, from UK departures to river journeys and fly-cruises.','New to cruising? Start with the kind of days you would enjoy.','<p>Understand ships, itineraries, cabins and the costs to compare before deciding whether a cruise is right for you.</p><h2>What does a cruise involve?</h2><p>Your ship is your base as you follow an itinerary, with time on board and opportunities to go ashore. Some journeys include days at sea; others focus on frequent stops. You do not need to know the cruise terminology before we start comparing options.</p><h2>The ship and route both matter</h2><p>A busy ship with lots of entertainment feels different from a smaller, quieter one. The places you visit, time in port and pace of the journey matter as much as the headline fare. I can help you work through those differences.</p><h2>Things worth thinking through</h2><h3>Ocean or river?</h3><p>Ocean cruises and river cruises offer different scales and itineraries. Compare the actual ship, onboard facilities, stops and how you get ashore, rather than assuming one style will suit everyone.</p><h3>UK departure or fly-cruise?</h3><p>A UK departure may avoid flying, but check travel to the port, parking and the sailing’s route. For a fly-cruise, look at flight times, baggage, transfers and the arrangements if journeys are disrupted.</p><h3>Cabins and atmosphere</h3><p>Compare inside, window and balcony options, cabin location and the exact layout. Think about dining arrangements, entertainment, quiet spaces and whether you want a family-friendly or adult-focused sailing.</p><h3>The total cost</h3><p>Check the particular fare’s meals, drinks, gratuities, excursions, internet and other charges. Inclusions differ between operators and fares; no inclusion or sailing availability is promised here.</p><h3>Getting around and going ashore</h3><p>For access requirements, check the cabin and bathroom, routes on board, embarkation and each port’s arrangements. Tender boats and shore excursions may involve different limitations; specific requirements need supplier confirmation.</p><h2>Styles to explore</h2><h3>A first cruise</h3><p>Start by comparing the balance of sea days and port visits, how long you want to be away and the atmosphere you prefer. A short sailing is one possibility, but the right itinerary matters more than simply choosing the shortest.</p><h3>A destination-led itinerary</h3><p>Choose places you want time to explore, then compare arrival times, departure times and the journey from the port. A destination name alone does not tell you how much of it you will see.</p><h3>A quieter river journey</h3><p>If the route appeals, look at the daily programme, excursions, ship layout and any walking involved. Check practical details for that specific itinerary.</p>','/images/destinations/cruise.jpg','Gentle ocean waves beneath a pale sky','50% 50%','Ready to talk through a cruise?','Tell me what appeals, what you are unsure about and whether you have particular dates or departure preferences.','published',2) on conflict(id) do nothing;
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000003','Couples Escapes','couples','A quiet base, a busy city or a few days away — it need not mean a luxury retreat.','Time away together, in a way that suits you both.','<p>Compare quiet beach stays, city and culture breaks, adults-only options and special occasions around your own priorities.</p><h2>There is no single couples holiday</h2><p>You might want days by the sea, good food close by or a city with plenty to explore. Not every couple wants luxury or a packed itinerary. I start with what each of you would like from the time away.</p><h2>Things worth thinking through</h2><h3>Atmosphere before labels</h3><p>Compare quieter resorts, adults-only accommodation and hotels open to all ages. An adults-only label does not by itself tell you whether somewhere is peaceful, lively or right for you.</p><h3>A few nights or a longer stay?</h3><p>For a short break, think about how much usable time remains after the journey. For longer trips, consider whether you want one base or a change of scene.</p><h3>Food and your surroundings</h3><p>Look beyond the room: dining options, opening times, nearby facilities and transport all affect how easily you can spend your days as you choose.</p><h3>Occasions and budget</h3><p>If it is a birthday, anniversary or another occasion, tell me what matters. Set a comfortable overall budget and prioritise the details you would value, rather than assuming everything needs an upgrade.</p><h2>Styles to explore</h2><h3>Beach time at your pace</h3><p>Consider a quieter coastal base with the option to explore. Check the setting and access to the beach rather than relying on a “romantic” description.</p><h3>City and culture</h3><p>Food, galleries, neighbourhoods and evenings out can shape a break together. A convenient base may leave more room in the day than a higher-rated hotel farther away.</p><h3>A simple short escape</h3><p>A workable journey, comfortable accommodation and a few things you both want to do may be enough. Leave some unscheduled time if that is how you like to travel.</p>','/images/destinations/couples.jpg','Modern white villa with a sunlit swimming pool','50% 50%','What would you both enjoy?','Share your ideas, dates and comfortable budget when you are ready to take the next step.','published',3) on conflict(id) do nothing;
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000004','City Breaks','city-breaks','Look beyond hotel stars to the neighbourhood, journey and time you have to explore.','Choose a base that makes the city easier to enjoy.','<p>Plan around location, transport, sightseeing and the full cost of a weekend or longer city stay.</p><h2>Location is part of the holiday</h2><p>A hotel’s star rating cannot tell you how easy it is to reach the places you want to see. I look at the journey, neighbourhood and getting around, alongside the accommodation itself.</p><h2>Things worth thinking through</h2><h3>A weekend or a little longer?</h3><p>Compare flight times with the number of full days you will have. A later arrival and early departure can make a short break feel shorter than the number of nights suggests.</p><h3>Centre or out of centre?</h3><p>A lower room rate farther out may mean more fares and travelling time. A central address is not automatically convenient either: check it against your own sightseeing priorities.</p><h3>Airport, transfers and public transport</h3><p>Check which airport you will use, the transfer journey and services at your arrival and departure times. Consider tickets, luggage and any changes between transport modes.</p><h3>Walking and accessibility</h3><p>Map realistic routes between the things you want to do. Hills, steps, surfaces and station access can matter; discuss specific access requirements and verify the relevant arrangements.</p><h3>Season, events and total spend</h3><p>Think about weather preferences, local events, opening days and advance reservations. Allow for meals, transport, attractions and any applicable local charges alongside the hotel rate.</p><h2>Styles to explore</h2><h3>A focused weekend</h3><p>Choose a small number of priorities and a base that makes them practical. Leave room for meals and time simply looking around.</p><h3>An extended city stay</h3><p>Extra days may make space for different neighbourhoods and a slower pace. Compare the cost of additional nights with how much more you would enjoy the trip.</p><h3>Culture with time outside the centre</h3><p>If you want a day trip, check travel time and the arrangements for returning. It should fit comfortably within the break rather than dominate it.</p>','/images/destinations/city.jpg','Historic European city architecture beside a canal','50% 50%','Have a city or a few dates in mind?','Tell me what you would like to see and how you prefer to spend your days.','published',4) on conflict(id) do nothing;
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000005','Something Different','something-different','Rail, touring, nature or several stops: explore a different way to spend your time away.','Start with an idea, rather than a familiar holiday format.','<p>Explore rail journeys, touring, multi-centre stays, nature and special-interest trips without assuming every combination is bookable.</p><h2>What has caught your interest?</h2><p>Perhaps it is the journey itself, a landscape, wildlife or an interest you would like more time for. You do not need a finished itinerary to start exploring the possibilities with me.</p><h2>Possibilities first, booking arrangements next</h2><p>More complex trips need an appropriate authorised New Travel booking structure. Before booking, the relevant organiser and responsibilities must be identified. An idea on this page is not a promise that I can combine and sell any set of travel services.</p><h2>Things worth thinking through</h2><h3>Pace and time in each place</h3><p>Moving often can make a trip interesting, but each change uses time. Think about luggage, unpacking and how long you want to stay before moving on.</p><h3>Connections and the complete journey</h3><p>Rail, flights and road transfers need workable connections. Check who provides each element and how disruption would be handled under the proposed booking arrangements.</p><h3>Your interest, in practical terms</h3><p>For wildlife, nature or special-interest travel, consider the season, daily activity, group size and any equipment needed. Sightings and particular experiences should never be treated as guaranteed.</p><h3>Comfort and overall budget</h3><p>Include the cost of moving between stops, meals and activities. Tell me about access needs and the pace you are comfortable with before an itinerary is narrowed down.</p><h2>Styles to explore</h2><h3>Scenic rail journeys</h3><p>Make the journey part of the appeal. Compare travel days, luggage arrangements, overnight stops and how you reach the stations.</p><h3>Touring or several centres</h3><p>A tour or more than one base may help you see different places. Look at guided versus independent time and whether the programme leaves enough breathing space.</p><h3>Nature, wildlife and particular interests</h3><p>A landscape, an unusual destination or a specific interest can give a trip its focus. Explore what is realistically offered and what the conditions involve.</p>','/images/destinations/different.jpg','Mountain landscape stretching into the distance','50% 50%','Have an idea you would like to explore?','Tell me what interests you and I can research the possibilities and the practical arrangements.','published',5) on conflict(id) do nothing;
insert into public.holiday_types(id,name,slug,introduction,heading,body,image,image_alt,image_position,closing_heading,closing_body,status,display_order) values ('b0000000-0000-4000-8000-000000000006','Accessible Travel','accessible','Individual requirements, practical questions and specific supplier confirmation.','Start with what works for you, then check the details.','<p>Explore the practical questions around rooms, bathrooms, journeys, equipment and local access. Suitability needs individual discussion and confirmation.</p><h2>Accessibility is individual</h2><p>A holiday described as accessible may not meet your requirements. I can help research the practical details and seek specific supplier confirmation, rather than relying on a label. These photographs illustrate holiday settings; they are not evidence of accessible facilities or a personal inspection.</p><h2>Things worth thinking through</h2><h3>Rooms and bathrooms</h3><p>Describe the practical features that matter, such as step-free access, door clearances, bed arrangements, a wet room or bathroom layout. An adapted-room label is a starting point for questions, not confirmation of suitability.</p><h3>Routes through the property</h3><p>Check the route between the room, restaurants, pool and other facilities, including gradients, surfaces, lifts and distances. Ask about the exact room and layout proposed.</p><h3>Transfers and local transport</h3><p>Consider every part of the journey, including airports or ports, vehicle access and getting around once you arrive. Transport assistance and equipment arrangements need to be checked separately.</p><h3>Mobility equipment</h3><p>Where equipment is needed, its dimensions, handling, storage, charging and any hire arrangements may need confirmation. Supply only the necessary practical details through an agreed secure workflow.</p><h3>Cruises and going ashore</h3><p>Cabin layouts, embarkation, tender arrangements and excursions can involve different requirements. Confirm each relevant element with the supplier for the specific sailing.</p><h2>Styles to explore</h2><h3>A single comfortable base</h3><p>Fewer changes of accommodation may simplify some journeys. The room, facilities and surroundings still need to be checked against your requirements.</p><h3>A city with a workable plan</h3><p>Consider transport, surfaces, distances and access to the places you want to visit. A convenient address alone does not establish suitability.</p><h3>A cruise, with the right checks</h3><p>Explore the ship and itinerary together. Suitable onboard arrangements do not automatically mean every port or excursion will work for you.</p>','/images/destinations/accessible.jpg','Open coastal landscape beside calm water; illustrative destination photograph','50% 50%','Would you like to discuss what you need?','Use the Holiday Brief to indicate that there are requirements to talk through privately. Detailed medical information is not needed there.','published',6) on conflict(id) do nothing;

notify pgrst,'reload schema';
commit;
